let db;const open=indexedDB.open('arabic-learning',1);open.onupgradeneeded=()=>{for(const n of ['content','assets'])open.result.createObjectStore(n)};await new Promise((r,j)=>{open.onsuccess=()=>{db=open.result;r()};open.onerror=()=>j(open.error)});
const read=async(store,key)=>{const value=await new Promise((r,j)=>{const q=db.transaction(store).objectStore(store).get(key);q.onsuccess=()=>r(q.result);q.onerror=()=>j(q.error)});if(value!==undefined||store!=='assets')return value;if(!builtinResourcePaths.has(key))return undefined;const response=await fetch('builtin/'+key.split('/').map(encodeURIComponent).join('/'));if(!response.ok)return undefined;return response.blob()};
const builtin=await fetch('data/builtin-library.json').then(r=>{if(!r.ok)throw Error('内置教材清单加载失败');return r.json()});
const builtinResourcePaths=new Set();
for(const b of builtin.books){if(b.cover)builtinResourcePaths.add(b.id+'/'+b.cover);for(const c of b.chapters)if(c.audio)builtinResourcePaths.add(b.id+'/'+c.audio)}
for(const n of builtin.notebooks)for(const w of n.words)if(w.audio)builtinResourcePaths.add(n.id+'/'+w.audio);
const saved=await read('content','library');
let library={books:(saved?.books||[]).filter(b=>b.id!=='demo-arabic'),notebooks:(saved?.notebooks||[]).filter(n=>n.id!=='demo-notes')};
for(const kind of ['books','notebooks'])for(const entry of builtin[kind]){const i=library[kind].findIndex(x=>x.id===entry.id);if(i<0)library[kind].push(entry);else if((library[kind][i].version||1)<(entry.version||1))library[kind][i]=entry;}
let state;try{state=JSON.parse(localStorage.getItem('arabic-state'))}catch{}state={settings:{font:30,bg:'#faf9f5',translation:'mask',language:'zh',mode:'reading'},progress:{},favorites:[],recent:[],playlists:[],...state};
let page='home',view='grid',tab='notebooks',query='',reader=null,notebook=null,card=0,flipped=false,wordView=state.wordView||'list',showPlayer=false,filter='all',sort='recent',audioUrl=null;
const persist=()=>localStorage.setItem('arabic-state',JSON.stringify(state));const toast=t=>{ $('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',3500)};
const coverUrls=new Map();
async function showCovers(){for(const el of document.querySelectorAll('[data-cover-book]')){const b=library.books.find(b=>b.id===el.dataset.coverBook);if(!b?.cover)continue;const key=b.id+'/'+b.cover;let url=coverUrls.get(key);if(!url){const blob=await read('assets',key);if(!blob)continue;url=URL.createObjectURL(blob);coverUrls.set(key,url)}if(el.isConnected){const img=document.createElement('img');img.src=url;img.alt=b.title+' 封面';img.className='cover-image';img.onerror=()=>{img.remove();el.classList.remove('has-image')};el.prepend(img);el.classList.add('has-image')}}}
const saveLibrary=()=>new Promise((r,j)=>{const t=db.transaction('content','readwrite');t.objectStore('content').put(library,'library');t.oncomplete=r;t.onerror=()=>j(t.error)});
function shell(body){$('#app').innerHTML=`<div class="shell"><header><div class="brand">${icon('book')}<div>Arabic Learning<small>READ · LISTEN · DISCOVER</small></div></div><span class="status"><i class="dot"></i>你的随身阿语书房</span></header>${body}</div><nav class="bottom">${[['home','home','首页'],['vocab','book','词汇'],['playlists','music','播放列表'],['me','user','我的']].map(([p,i,t])=>`<button data-page="${p}" class="nav ${page===p?'active':''}">${icon(i)}${t}</button>`).join('')}</nav>`;applyPersonalization()}
function render(){if(reader)return renderReader();if(page==='home')home();if(page==='vocab')vocab();if(page==='playlists')playlists();if(page==='me')me()}
function home(){const b=library.books[0];shell(`${b?`<section class="hero"><div><span class="eyebrow">YOUR NEXT CHAPTER / 继续阅读</span><h1>${esc(b.title)}</h1><p>阿拉伯语 · ${b.chapters.length} 个章节 · 慢慢读，听见新的世界</p><button class="primary" data-book="${esc(b.id)}">${icon('play')}打开阅读器</button></div><div class="hero-art" lang="ar" dir="rtl">اقرأ</div></section>`:''}<div class="section-head"><h2>我的阅读材料<span class="count">${library.books.length} 本</span></h2><button class="primary" data-action="import">${icon('plus')}导入材料</button></div><div class="filters">${[['all','全部'],['books','书籍'],['queued','已加入播放列表']].map(([id,t])=>`<button class="chip ${filter===id?'active':''}" data-filter="${id}">${t}</button>`).join('')}</div><div class="tools"><div class="search">${icon('search')}<input id="search" placeholder="搜索你的书籍和阅读材料" value="${esc(query)}"></div><div class="row"><select id="sort" aria-label="排序"><option value="recent" ${sort==='recent'?'selected':''}>最近导入</option><option value="title" ${sort==='title'?'selected':''}>书名排序</option></select>${ib(view==='grid'?'list':'grid','view','切换视图')}</div></div><div id="books"></div>`);drawBooks()}
function drawBooks(){let books=library.books.filter(b=>b.title.includes(query)&&(filter!=='queued'||state.playlists.some(p=>p.items.some(i=>i.bookId===b.id))));if(sort==='title')books=[...books].sort((a,b)=>a.title.localeCompare(b.title));$('#books').className=view;$('#books').innerHTML=books.map((b,i)=>`<button class="book" data-book="${esc(b.id)}"><div class="cover" data-cover-book="${esc(b.id)}" style="background:${['#dfe7d8','#e9e2d2','#dce6e1'][i%3]}"><span class="ar" lang="ar" dir="rtl">${esc(b.coverTitle||'كتاب')}</span><small>ARABIC READER</small></div><div class="book-info"><h3>${esc(b.title)}</h3><p>${b.chapters.length} 个章节 · ${b.language==='ar'?'阿拉伯语':esc(b.language)}</p></div></button>`).join('')||'<div class="empty">还没有符合条件的材料。</div>';showCovers()}
function wordRow(w,index=0){const s=state.cardSettings;return `<div class="word" data-word-index="${index}"><div><button class="ar word-sound" lang="${esc(w.language||'ar')}" dir="${w.language==='ar'||!w.language?'rtl':'ltr'}" data-pronounce-index="${index}" aria-label="朗读 ${esc(w.word)}">${esc(w.word)}</button><div class="word-transliteration">${esc(w.transliteration||'暂无转写')}</div><p>${esc(w.meaning||'尚无释义')}</p>${s.example&&w.example?`<div class="ar entry-example" dir="${w.language==='ar'?'rtl':'ltr'}">${esc(w.example)}</div>`:''}${s.exampleTranslation==='on'?`<p class="entry-example-translation">${esc(w.exampleTranslation||'暂无例句翻译')}</p>`:s.exampleTranslation==='tap'?`<button class="entry-example-translation note" data-entry-translation="${index}" aria-expanded="false">点击显示例句翻译</button>`:''}</div><button class="icon" data-word="${esc(w.word)}" aria-label="查看词条">↗</button></div>`}
function playlists(){shell(`<div class="section-head"><h2>播放列表</h2><button class="primary" data-action="new-playlist">${icon('plus')}新建</button></div><p class="note">Remember Me</p>${state.playlists.map(p=>`<section class="book" style="padding:20px;margin:15px 0"><div class="section-head"><h3>${esc(p.title)}</h3><span>${p.items.length} 个章节</span></div>${p.items.map((i,k)=>{const b=library.books.find(b=>b.id===i.bookId),c=b?.chapters.find(c=>c.id===i.chapterId);return `<div class="row"><button class="setting" style="width:auto;flex:1" data-book="${esc(i.bookId)}" data-chapter="${esc(i.chapterId)}">${icon('play')} ${esc(c?.title||'材料未导入')}<small>${esc(b?.title||'')}</small></button><button data-remove="${esc(p.id)}" data-index="${k}" aria-label="移除">×</button></div>`}).join('')}</section>`).join('')||'<div class="empty">建立第一个听读列表。<br>在阅读器中点击加号，将章节加入列表。</div>'}`)}
function me(){shell(`<div class="section-head"><h2>我的学习空间</h2></div><section class="hero profile-hero"><div><span class="eyebrow">LITTLE BY LITTLE</span><h1 id="profile-banner-title">${esc(state.personalization?.bannerText||'MIY FLIZ')}</h1><p>${library.books.length} 本书 · ${library.notebooks.length} 个词本 · ${state.favorites.length} 个收藏</p></div><div class="hero-art">تعلم</div></section><button class="setting" data-action="personalization">个性化设置</button><button class="setting" data-action="dictionary-search">内置阿拉伯语—英语词典<small>英文释义 · Wiktionary / Kaikki · 无需导入</small></button><button class="setting" data-action="import">导入学习材料<small>选择 ZIP，一次导入书籍、词本及配套资源</small></button><button class="setting" data-action="backup">导出学习数据<small>备份收藏、播放列表、阅读位置和设置；不含材料音频</small></button><button class="setting" data-action="restore">恢复学习数据<small>选择之前导出的 JSON 备份</small></button>`)}
async function openBook(id,cid){const b=library.books.find(b=>b.id===id);if(!b)return toast('请先导入对应材料');const p=state.progress[id];reader={book:b,chapter:b.chapters.find(c=>c.id===(cid||p?.chapterId))||b.chapters[0]};showPlayer=false;await loadAudio();render()}
function words(s){return s.words||s.text.trim().split(/\s+/).map((text,i)=>({text,id:`${s.id}-w${i}`}))}
function renderReader(){const {book:b,chapter:c}=reader;document.documentElement.style.setProperty('--reading',state.settings.bg);document.documentElement.style.setProperty('--size',state.settings.font+'px');$('#app').innerHTML=`<main class="reader"><div class="reader-top"><button class="icon" data-action="exit-reader" aria-label="返回书架">${icon('back')}<span class="back-label">书架</span></button><div class="tools">${ib('settings','reading-settings','阅读设置')}${ib('translate','translation-settings','翻译')}${ib('music','audio-panel','音频播放')}${ib('plus','add-playlist','添加到播放列表')}${ib('more','more','更多设置')}</div></div><article class="reader-body"><span class="chapter-meta">${esc(b.title)} / ${state.settings.mode==='listening'?'收听模式 · 长按查词':'阅读模式 · 单击查词'}</span><h1><button data-action="chapters">${esc(c.title)} ⌄</button></h1>${c.sentences.map(s=>`<section class="sentence" data-sentence="${esc(s.id)}"><div class="original" lang="${esc(b.language)}" dir="${b.language==='ar'?'rtl':'ltr'}">${words(s).map((w,i)=>`<span class="token" role="button" tabindex="0" data-sid="${esc(s.id)}" data-wi="${i}">${esc(w.text)}</span>`).join(' ')}</div>${state.settings.translation==='off'?'':`<div role="button" tabindex="0" class="translation ${state.settings.translation==='mask'?'mask':''}" aria-label="${state.settings.translation==='mask'?'点击显示翻译':'翻译'}">${esc(s.translations?.[state.settings.language]||'此语言暂无翻译')}</div>`}</section>`).join('')}<p class="note">${c.audio?'':'本章尚无配套音频，导入含音频的材料包后即可收听。'}</p><div class="section-head"><button class="secondary" data-action="chapter-prev">上一章</button><button class="secondary" data-action="chapter-next">下一章</button></div></article>${showPlayer?`<div class="player"><div class="player-line"><div><b>${esc(c.title)}</b><br><small id="audio-time">${c.audio?'准备播放':'暂无配套音频'}</small></div><div class="row">${ib('prev','sentence-prev','上一句')}<button class="play" data-action="toggle-play" aria-label="播放或暂停">${icon($('#audio').paused?'play':'pause')}</button>${ib('next','sentence-next','下一句')}${ib('close','close-player','收起播放栏')}</div></div><input id="seek" type="range" min="0" max="100" value="0" aria-label="播放进度"></div>`:''}</main>`;bindTokens()}
async function loadAudio(){const a=$('#audio');a.pause();a.removeAttribute('src');a.load();if(audioUrl)URL.revokeObjectURL(audioUrl);audioUrl=null;const c=reader.chapter;if(c.audio){const blob=await read('assets',reader.book.id+'/'+c.audio);if(blob){audioUrl=URL.createObjectURL(blob);a.src=audioUrl;const p=state.progress[reader.book.id];if(p?.chapterId===c.id)a.addEventListener('loadedmetadata',()=>{a.currentTime=Math.min(p.time||0,a.duration||0)},{once:true})}else toast('未找到对应音频')}}
function bindTokens(){document.querySelectorAll('.token').forEach(el=>{let timer,long=false;el.onpointerdown=()=>{long=false;timer=setTimeout(()=>{long=true;lookupToken(el)},500)};el.onpointerup=()=>clearTimeout(timer);el.onpointercancel=()=>clearTimeout(timer);el.onpointerleave=()=>clearTimeout(timer);el.onclick=()=>{if(long)return;if(state.settings.mode==='listening')seekWord(el);else lookupToken(el)};el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();el.click()}}})}
function tokenData(el){const s=reader.chapter.sentences.find(s=>s.id===el.dataset.sid);return {s,w:words(s)[+el.dataset.wi]}}
function lookupToken(el){const {s,w}=tokenData(el);lookup(w.text,s.text)}
let dictionaryPromise=null;
const normalizeArabic=t=>String(t).replace(/[\u064B-\u065F\u0670\u0640]/g,'').replace(/^[^\p{L}]+|[^\p{L}]+$/gu,'');
async function dictionaryMatches(text){
 dictionaryPromise ||= fetch('data/dictionary.json').then(r=>{if(!r.ok)throw Error('内置词典加载失败');return r.json()}).catch(e=>{dictionaryPromise=null;throw e});
 const dictionary=await dictionaryPromise,key=normalizeArabic(text),candidates=[key];
 // Only suggest an affix-stripped candidate when the actual dictionary contains it.
 if(/^[وف]/.test(key))candidates.push(key.slice(1));
 for(const k of [...candidates]){if(k.startsWith('ال'))candidates.push(k.slice(2));if(/^[بكل]/.test(k)){candidates.push(k.slice(1));if(k.slice(1).startsWith('ال'))candidates.push(k.slice(3))}}
 for(const k of [...new Set(candidates)]){let rows=dictionary.entries[k];if(!rows){const bases=dictionary.forms[k]||[];rows=bases.flatMap(base=>dictionary.entries[base]||[])}if(rows?.length)return {rows:rows.slice(0,6),candidate:k,normalized:key,source:dictionary.metadata};}
 return null;
}
async function lookup(text,example=''){
 stopCards();modal('查词','<p class="note">正在查询本课词表与内置词典……</p>');const requestModal=modalEpoch;
 const candidates=[...library.notebooks.filter(n=>reader&&n.bookId===reader.book.id),...library.notebooks.filter(n=>!reader||n.bookId!==reader.book.id)];
 const found=candidates.flatMap(n=>n.words.map(w=>({...w,language:w.language||n.language||'ar',_assetOwner:n.id}))).find(w=>normalizeArabic(w.word)===normalizeArabic(text));
 let match=null,error='';if(!found)try{match=await dictionaryMatches(text)}catch(e){error=e.message}
 if(requestModal!==modalEpoch||!$('#panel').open)return;
 const gloss=match?.rows.flatMap(row=>row.glosses||[]).filter(Boolean).slice(0,8).join('; ');
 const w=found||{word:text,meaning:gloss||'本课词表与内置词典暂无匹配释义',meaningLanguage:gloss?'en':'zh',example,language:'ar',dictionarySource:gloss?'Wiktionary / Kaikki':undefined};
 selectedLookupWord=w;state.recent=state.recent.filter(x=>x.word!==text);state.recent.unshift(w);persist();
 modal('词条',`<div class="ar" dir="rtl" style="font-size:44px">${esc(text)}</div><p>${esc(w.meaning)}</p>${match?`<p class="note">英文释义 · Wiktionary / Kaikki${match.candidate!==match.normalized?' · 去附着词后的候选匹配，请结合上下文确认':''}</p><a href="https://en.wiktionary.org/wiki/${encodeURIComponent(match.rows[0]?.word||text)}#Arabic" target="_blank" rel="noopener">查看原词条与来源</a>`:''}${error?`<p class="note">${esc(error)}</p>`:''}<p class="ar" dir="rtl">${esc(w.example||example)}</p><button class="secondary" data-action="lookup-card">卡片模式</button> <button class="primary" id="favorite-word">${state.favorites.some(x=>x.word===text)?'取消收藏':'加入收藏'}</button>`);
 $('#favorite-word').onclick=()=>{const i=state.favorites.findIndex(x=>x.word===text);if(i<0)state.favorites.push(w);else state.favorites.splice(i,1);persist();$('#panel').close();toast(i<0?'已收藏':'已取消收藏')};
}
function dictionarySearch(){modal('内置阿英词典',`<p class="note">Wiktionary / Kaikki · 英文释义；不是中文译文。支持忽略元音符号与词形索引，不保证所有变位或方言覆盖。</p><form id="dictionary-form"><label>阿拉伯语单词<input id="dictionary-query" dir="rtl" required></label><button class="primary">查词</button></form><p class="note"><a href="THIRD-PARTY-NOTICES.md" target="_blank">词典来源与许可说明</a></p>`);$('#dictionary-form').onsubmit=e=>{e.preventDefault();const value=$('#dictionary-query').value.trim();if(value)lookup(value)}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="dictionary-search"]'))dictionarySearch()});
async function seekWord(el){const selectedReader=reader;const {w}=tokenData(el);if(!reader.chapter.audio||!$('#audio').src)return toast('本章没有可播放的音频');if(!Number.isFinite(w.start))return toast('该单词缺少时间戳，无法精确定位');$('#audio').currentTime=w.start;await play();if(reader!==selectedReader)return;showPlayer=true;renderReader()}
async function play(){if(!$('#audio').src)return toast('请先导入配套音频');try{await $('#audio').play()}catch{toast('音频无法播放，请检查文件或再次点击播放')}}
let modalEpoch=0;
function modal(title,body){modalEpoch++;$('#panel').innerHTML=`<div class="section-head"><h2>${title}</h2>${ib('close','close-panel','关闭')}</div>${body}`;if(!$('#panel').open)$('#panel').showModal()}
function settings(type){if(type==='reading-settings'){modal('阅读设置',`<label>字体大小 <output id="font-out">${state.settings.font}px</output><input id="font" type="range" min="22" max="48" value="${state.settings.font}"></label><p>阅读背景</p><div class="row">${['#faf9f5','#edf1e7','#e9e0cf','#d8e4dd'].map(bg=>`<button class="secondary" data-bg="${bg}" style="background:${bg}" aria-label="背景 ${bg}">Aa</button>`).join('')}</div>`);$('#font').oninput=e=>{state.settings.font=+e.target.value;$('#font-out').textContent=e.target.value+'px';persist();document.documentElement.style.setProperty('--size',e.target.value+'px')}}else if(type==='translation-settings'){const langs=[...new Set(reader.chapter.sentences.flatMap(s=>Object.keys(s.translations||{})))];modal('翻译',`<label>翻译语言<select id="translation-language">${langs.map(l=>`<option ${l===state.settings.language?'selected':''} value="${esc(l)}">${l==='zh'?'中文':esc(l)}</option>`).join('')}</select></label><label>显示方式<select id="translation-mode">${[['on','直接显示'],['off','关闭翻译'],['mask','遮盖 · 点击揭示']].map(([v,t])=>`<option value="${v}" ${v===state.settings.translation?'selected':''}>${t}</option>`).join('')}</select></label>`);$('#translation-mode').onchange=e=>{state.settings.translation=e.target.value;persist();renderReader()};$('#translation-language').onchange=e=>{state.settings.language=e.target.value;persist();renderReader()}}else{modal('更多设置',`<label>学习模式<select id="learning-mode"><option value="reading" ${state.settings.mode==='reading'?'selected':''}>阅读 · 单击查词</option><option value="listening" ${state.settings.mode==='listening'?'selected':''}>收听 · 单击定位，长按查词</option></select></label><label>播放速度<select id="rate">${[.75,1,1.25,1.5].map(v=>`<option ${$('#audio').playbackRate===v?'selected':''}>${v}</option>`).join('')}</select></label><button class="setting" data-action="sleep-settings">定时停止播放<small>15／30／45／60 分钟或自定义</small></button><button class="setting" data-action="grammar">查看本课语法<small>本课新语法、复习要点与例句</small></button><button class="setting" data-action="chapters">章节目录</button>`);$('#learning-mode').onchange=e=>{state.settings.mode=e.target.value;persist();renderReader()};$('#rate').onchange=e=>$('#audio').playbackRate=+e.target.value}}
function showGrammar(){
 const chapter=reader.chapter;
 const entries=Array.isArray(chapter.grammar)?chapter.grammar:[];
 if(!entries.length){modal('本课语法',`<p class="note">${esc(chapter.title)}</p><div class="empty">本课暂无语法说明。<br>导入包含章节语法的材料包后即可查看。</div>`);return}
 modal('本课语法',`<p class="note">${esc(chapter.title)}</p>${entries.map(g=>`<section class="grammar-entry"><div class="row"><span class="count">${g.status==='review'?'复习语法':'新语法'}</span><h3>${esc(g.title)}</h3></div><p class="grammar-explanation">${esc(g.explanation)}</p>${(Array.isArray(g.examples)?g.examples:[]).map(ex=>{const sentence=chapter.sentences.find(s=>s.id===ex.sentenceId);return `<div class="grammar-example">${sentence?`<p class="ar" lang="${esc(reader.book.language)}" dir="${reader.book.language==='ar'?'rtl':'ltr'}">${esc(sentence.text)}</p>`:'<p class="note">对应课文例句未找到</p>'}<p>${esc(ex.translation||sentence?.translations?.[state.settings.language]||'')}</p>${ex.note?`<p class="note">${esc(ex.note)}</p>`:''}</div>`}).join('')}</section>`).join('')}`)
}
function chapters(){modal('章节目录',reader.book.chapters.map(c=>`<button class="setting" data-book="${esc(reader.book.id)}" data-chapter="${esc(c.id)}">${esc(c.title)}${c.id===reader.chapter.id?' · 当前':''}</button>`).join(''))}
function newPlaylist(after){modal('新建播放列表','<form id="playlist-form"><label>列表名称<input id="playlist-name" required maxlength="60" placeholder="例如：每天听一点"></label><button class="primary">创建</button></form>');$('#playlist-form').onsubmit=e=>{e.preventDefault();const title=$('#playlist-name').value.trim();if(!title)return;state.playlists.push({id:crypto.randomUUID(),title,items:[]});persist();$('#panel').close();if(after)after();else render()}}
function addPlaylist(){modal('添加当前章节',state.playlists.map(p=>`<button class="setting" data-add="${esc(p.id)}">${esc(p.title)} <small>${p.items.length} 个章节</small></button>`).join('')+'<button class="setting" data-action="new-playlist-add">＋ 新建播放列表</button>')}
const audio=$('#audio');audio.ontimeupdate=()=>{if(!reader)return;state.progress[reader.book.id]={chapterId:reader.chapter.id,time:audio.currentTime};if($('#audio-time'))$('#audio-time').textContent=`${fmt(audio.currentTime)} / ${fmt(audio.duration)}`;if($('#seek')&&audio.duration)$('#seek').value=audio.currentTime/audio.duration*100;document.querySelectorAll('.token').forEach(el=>{const {w}=tokenData(el);el.classList.toggle('playing',Number.isFinite(w.start)&&audio.currentTime>=w.start&&audio.currentTime<(w.end??w.start+.5))})};audio.onpause=()=>{persist();if(reader&&showPlayer)renderReader()};audio.onended=()=>toast('本章播放完毕');window.addEventListener('pagehide',persist);const fmt=t=>Number.isFinite(t)?`${Math.floor(t/60)}:${String(Math.floor(t%60)).padStart(2,'0')}`:'0:00';
function sentenceJump(dir){const starts=reader.chapter.sentences.map(s=>words(s)[0]?.start).filter(Number.isFinite);if(!starts.length)return toast('本章缺少句子时间戳');const t=audio.currentTime;const target=dir>0?starts.find(x=>x>t+.15):[...starts].reverse().find(x=>x<t-.5);if(target===undefined)return toast(dir>0?'已经是最后一句':'已经是第一句');audio.currentTime=target;play()}
document.addEventListener('click',async e=>{const el=e.target.closest('button,[data-action],.translation');if(!el)return;try{if(el.dataset.page){audio.pause();page=el.dataset.page;notebook=null;render();return}if(el.dataset.book){$('#panel').close();await openBook(el.dataset.book,el.dataset.chapter);return}if(el.dataset.notebook){notebook=el.dataset.notebook;card=0;flipped=false;render();return}if(el.dataset.tab){tab=el.dataset.tab;render();return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.word){lookup(el.dataset.word);return}if(el.dataset.bg){state.settings.bg=el.dataset.bg;persist();renderReader();return}if(el.dataset.remove){state.playlists.find(p=>p.id===el.dataset.remove).items.splice(+el.dataset.index,1);persist();render();return}if(el.dataset.add){const p=state.playlists.find(p=>p.id===el.dataset.add);if(!p.items.some(i=>i.bookId===reader.book.id&&i.chapterId===reader.chapter.id)){p.items.push({bookId:reader.book.id,chapterId:reader.chapter.id});persist();toast('已加入播放列表')}else toast('该章节已在列表中');$('#panel').close();return}if(el.classList.contains('translation')){el.classList.remove('mask');return}const a=el.dataset.action;if(['reading-settings','translation-settings','more'].includes(a))return settings(a);switch(a){case 'view':view=view==='grid'?'list':'grid';render();break;case 'import':$('#import').click();break;case 'restore':$('#restore').click();break;case 'backup':downloadBackup();break;case 'exit-reader':audio.pause();reader=null;render();break;case 'chapters':chapters();break;case 'grammar':showGrammar();break;case 'chapter-next':case 'chapter-prev':{const idx=reader.book.chapters.indexOf(reader.chapter)+(a==='chapter-next'?1:-1),c=reader.book.chapters[idx];if(c)await openBook(reader.book.id,c.id);else toast('没有更多章节');break}case 'audio-panel':showPlayer=!showPlayer;renderReader();break;case 'close-player':showPlayer=false;renderReader();break;case 'toggle-play':if(audio.paused)await play();else audio.pause();if(reader)renderReader();break;case 'sentence-prev':sentenceJump(-1);break;case 'sentence-next':sentenceJump(1);break;case 'close-panel':$('#panel').close();break;case 'add-playlist':addPlaylist();break;case 'new-playlist':newPlaylist();break;case 'new-playlist-add':newPlaylist(addPlaylist);break;case 'back-notebook':notebook=null;render();break;case 'word-view':wordView=wordView==='list'?'card':'list';render();break;case 'flip':flipped=!flipped;render();break;case 'card-prev':case 'card-next':{const n=library.notebooks.find(n=>n.id===notebook);card=(card+(a==='card-next'?1:-1)+n.words.length)%n.words.length;flipped=false;render();break}}}catch(error){toast(error.message||'操作失败')}});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;drawBooks()}if(e.target.id==='seek'&&audio.duration)audio.currentTime=+e.target.value/100*audio.duration});document.addEventListener('change',e=>{if(e.target.id==='sort'){sort=e.target.value;drawBooks()}});document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.classList.contains('translation'))e.target.click()});
async function downloadBackup(){const personalizationBackground=await exportBackground();const blob=new Blob([JSON.stringify({format:'arabic-learning-backup',version:1,createdAt:new Date().toISOString(),state,personalizationBackground},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='arabic-learning-backup.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
$('#restore').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;const b=JSON.parse(await f.text());if(b.format!=='arabic-learning-backup'||b.version!==1||!Array.isArray(b.state?.favorites)||!Array.isArray(b.state?.playlists)||!b.state?.settings)throw Error('不是兼容的学习数据备份');modal('恢复学习数据','<p>恢复将替换当前收藏、进度、播放列表和设置，材料保持不变。建议先导出当前备份。</p><button class="primary" id="confirm-restore">确认恢复</button>');$('#confirm-restore').onclick=async()=>{try{const restoredImage=await backgroundFromBackup(b.personalizationBackground);await storeProfileBackground(restoredImage);stopCards();state=b.state;state.cardSettings={meaning:'tap',example:true,exampleTranslation:'tap',transliteration:false,seconds:4,...state.cardSettings};state.reviews=state.reviews||{};state.reviewHistory=state.reviewHistory||[];state.personalization={pageBackground:'#faf9f5',iconColor:'#28735e',bannerText:'MIY FLIZ',launcherColor:'green',...state.personalization};persist();applyPersonalization();$('#panel').close();render();toast('学习数据已恢复')}catch(error){toast('恢复失败：'+error.message)}}}catch(err){toast(err.message)}finally{e.target.value=''}};
// ZIP central directory reader: stored and deflate only. No filesystem extraction.
async function unzip(file){if(file.size>300*1024*1024)throw Error('首版材料包上限为 300MB，请按章节拆分');const buffer=await file.arrayBuffer(),d=new DataView(buffer),bytes=new Uint8Array(buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(d.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('ZIP 文件损坏');const count=d.getUint16(end+10,true);if(count>2000)throw Error('文件数量超过上限');let pos=d.getUint32(end+16,true),total=0;const files=new Map();for(let i=0;i<count;i++){if(d.getUint32(pos,true)!==0x02014b50)throw Error('ZIP 目录不完整');const flag=d.getUint16(pos+8,true),method=d.getUint16(pos+10,true),size=d.getUint32(pos+20,true),raw=d.getUint32(pos+24,true),nl=d.getUint16(pos+28,true),xl=d.getUint16(pos+30,true),cl=d.getUint16(pos+32,true),offset=d.getUint32(pos+42,true),name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nl));pos+=46+nl+xl+cl;if(name.endsWith('/'))continue;if(flag&1)throw Error('不支持加密 ZIP');if(name.includes('..')||name.startsWith('/')||name.includes('\\'))throw Error('材料包包含不安全路径');total+=raw;if(total>600*1024*1024)throw Error('解压后材料超过上限');if(d.getUint32(offset,true)!==0x04034b50)throw Error('ZIP 资源损坏');const start=offset+30+d.getUint16(offset+26,true)+d.getUint16(offset+28,true);let data=bytes.slice(start,start+size);if(method===8){const stream=new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));data=new Uint8Array(await new Response(stream).arrayBuffer())}else if(method!==0)throw Error('不支持此 ZIP 压缩方式，请使用普通 ZIP');if(data.length!==raw)throw Error('资源大小校验失败');files.set(name,data)}return files}
function validatePackage(m,files){if(m.format!=='arabic-learning-material'||m.schemaVersion!==1)throw Error('材料包格式或版本不支持');if(!Array.isArray(m.books)||!Array.isArray(m.notebooks)||!m.books.length&&!m.notebooks.length)throw Error('材料清单必须包含书籍或词本');const ids=new Set();for(const b of m.books){if(typeof b.id!=='string'||!b.id||ids.has(b.id)||!b.title||!b.language||!Array.isArray(b.chapters)||!b.chapters.length)throw Error('书籍信息缺失或编号重复');if(b.cover&&(!files.has(b.cover)||!/^.+\.(png|jpe?g|webp)$/i.test(b.cover)))throw Error('缺少封面或封面格式不支持');ids.add(b.id);const cids=new Set();for(const c of b.chapters){if(!c.id||cids.has(c.id)||!c.title||!Array.isArray(c.sentences))throw Error('章节信息无效');cids.add(c.id);if(c.audio&&!files.has(c.audio))throw Error('缺少音频：'+c.audio);const sids=new Set();for(const s of c.sentences){if(!s.id||sids.has(s.id)||typeof s.text!=='string')throw Error('句子信息无效');sids.add(s.id);if(s.words)for(const w of s.words)if(typeof w.text!=='string'||w.start!==undefined&&(!Number.isFinite(w.start)||w.start<0)||w.end!==undefined&&(!Number.isFinite(w.end)||w.end<w.start))throw Error('单词时间戳无效')}}}ids.clear();for(const n of m.notebooks){if(!n.id||ids.has(n.id)||!n.title||!Array.isArray(n.words)||n.words.some(w=>typeof w.word!=='string'||typeof w.meaning!=='string'))throw Error('词本信息无效');ids.add(n.id);for(const w of n.words){if(w.audio&&(!files.has(w.audio)||!/^.+\.(mp3|wav|m4a|ogg)$/i.test(w.audio)))throw Error('缺少单词音频或格式不支持');if(w.transliteration!==undefined&&typeof w.transliteration!=='string')throw Error('转写字段无效');if(w.exampleTranslation!==undefined&&typeof w.exampleTranslation!=='string')throw Error('例句翻译字段无效')}}}
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;toast('正在检查材料包…');const files=await unzip(file);if(!files.has('manifest.json'))throw Error('ZIP 根目录缺少 manifest.json');const m=JSON.parse(new TextDecoder().decode(files.get('manifest.json')));validatePackage(m,files);const duplicate=m.books.some(b=>library.books.some(x=>x.id===b.id))||m.notebooks.some(n=>library.notebooks.some(x=>x.id===n.id));modal('确认导入',`<p>${esc(m.title||file.name)}</p><p>${m.books.length} 本书 · ${m.notebooks.length} 个词本</p>${duplicate?'<label>发现已有材料<select id="duplicate"><option value="skip">跳过已有材料</option><option value="update">更新已有材料（保留学习记录）</option><option value="copy">另存为新材料</option></select></label><p class="note">更新后若正文或音频发生变化，将重置该书播放位置，收藏与列表保留。</p>':''}<button class="primary" id="confirm-import">导入材料</button>`);$('#confirm-import').onclick=async()=>{try{$('#confirm-import').disabled=true;const mode=$('#duplicate')?.value||'skip';const next=structuredClone(library),assets=[];for(const kind of ['books','notebooks'])for(const original of m[kind]){const item=structuredClone(original),idx=next[kind].findIndex(x=>x.id===item.id);if(idx>=0&&mode==='skip')continue;if(idx>=0&&mode==='copy')item.id+='-'+crypto.randomUUID();if(kind==='notebooks')for(const w of item.words)if(w.audio){const ext=w.audio.split('.').pop().toLowerCase();assets.push([item.id+'/'+w.audio,new Blob([files.get(w.audio)],{type:({mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',ogg:'audio/ogg'})[ext]})])}if(kind==='books'&&item.cover){const ext=item.cover.split('.').pop().toLowerCase();assets.push([item.id+'/'+item.cover,new Blob([files.get(item.cover)],{type:({png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp'})[ext]})])}if(kind==='books')for(const c of item.chapters)if(c.audio){const ext=c.audio.split('.').pop().toLowerCase();assets.push([item.id+'/'+c.audio,new Blob([files.get(c.audio)],{type:({mp3:'audio/mpeg',wav:'audio/wav',m4a:'audio/mp4',ogg:'audio/ogg'})[ext]||'application/octet-stream'})])}if(idx>=0&&mode==='update')next[kind][idx]=item;else next[kind].unshift(item)}await new Promise((r,j)=>{const tx=db.transaction(['content','assets'],'readwrite');tx.objectStore('content').put(next,'library');for(const [key,blob]of assets)tx.objectStore('assets').put(blob,key);tx.oncomplete=r;tx.onerror=()=>j(tx.error)});if(mode==='update')for(const b of m.books)delete state.progress[b.id];for(const url of coverUrls.values())URL.revokeObjectURL(url);coverUrls.clear();library=next;persist();$('#panel').close();page='home';render();toast('材料导入完成')}catch(err){toast('导入失败：'+err.message);$('#confirm-import').disabled=false}}}catch(err){toast('导入失败：'+err.message)}finally{e.target.value=''}};
// Shared vocabulary presentation and a transparent, simple spaced-review schedule.
state.cardSettings={meaning:'tap',example:true,exampleTranslation:'tap',transliteration:false,seconds:4,...state.cardSettings};
state.reviews=state.reviews||{};state.reviewHistory=state.reviewHistory||[];
let selectedLookupWord=null,chapterFilter='all';
let singleWords=null,studyFilter='due',autoCards=false,autoHandle=null,cardAudio=new Audio(),cardAudioUrl=null,autoGeneration=0,sleepDeadline=0,lastCardSwipe=0;
function wordKey(w){return `${w.language||'ar'}:${w.lemma||w.word}`}
function allWordEntries(){const map=new Map();for(const n of library.notebooks)for(const w of n.words){const entry={...w,language:w.language||n.language||'ar',_assetOwner:n.id};if(!map.has(wordKey(entry)))map.set(wordKey(entry),entry)}for(const w of [...state.recent,...state.favorites])if(!map.has(wordKey(w)))map.set(wordKey(w),w);return [...map.values()]}
function enrichWord(w){return allWordEntries().find(x=>wordKey(x)===wordKey(w))||w}
function activeWords(){if(singleWords)return singleWords.map(enrichWord);if(notebook){const n=library.notebooks.find(n=>n.id===notebook);return (n?.words||[]).filter(w=>chapterFilter==='all'||w.chapterIds?.includes(chapterFilter)).map(w=>({...w,language:w.language||n.language||'ar',_assetOwner:n.id}))}if(tab==='learning')return allWordEntries().filter(w=>{const r=state.reviews[wordKey(w)];return studyFilter==='all'||studyFilter==='due'?(studyFilter==='all'||!r||r.due<=Date.now()):r?.rating===studyFilter}).sort((a,b)=>(state.reviews[wordKey(a)]?.due||0)-(state.reviews[wordKey(b)]?.due||0));return (state[tab]||[]).map(enrichWord)}
function reviewSchedule(previous,rating,now){let days=previous?.days||0;if(rating==='stranger')return {rating,days:0,due:now+10*60000};if(rating==='vague')return {rating,days:1,due:now+86400000};days=days>=1?Math.min(days*2.5,180):3;return {rating,days,due:now+days*86400000}}
function rateCurrent(rating){const list=activeWords(),w=list[card];if(!w)return;const key=wordKey(w),now=Date.now();state.reviews[key]=reviewSchedule(state.reviews[key],rating,now);state.reviewHistory.push({id:crypto.randomUUID(),key,rating,at:now});persist();stopCards();flipped=false;const next=activeWords();card=Math.min(tab==='learning'&&studyFilter!=='all'?card:card+1,Math.max(0,next.length-1));vocab()}
function cardMarkup(w){const s=state.cardSettings,shown=flipped||s.meaning==='on',exShown=s.exampleTranslation==='on'||flipped;return `<div class="flash" role="group" tabindex="0" data-action="shared-flip" aria-label="单词卡片"><button class="ar word-sound" data-pronounce-index="${card}" dir="${w.language==='ar'?'rtl':'ltr'}" aria-label="朗读 ${esc(w.word)}">${esc(w.word)}</button>${w.meaningLanguage==='en'?'<small>英文释义 · Wiktionary / Kaikki</small>':''}${s.transliteration?`<small>${esc(w.transliteration||'暂无转写')}</small>`:''}<p data-card-meaning>${shown?esc(w.meaning||'暂无释义'):'轻触卡片，查看释义'}</p>${s.example||s.exampleTranslation!=='off'?`<div class="card-example">${s.example&&w.example?`<span class="ar card-example-original" dir="${w.language==='ar'?'rtl':'ltr'}">${esc(w.example)}</span>`:''}${s.exampleTranslation!=='off'?`<p data-card-example-translation>${exShown?esc(w.exampleTranslation||'暂无例句翻译'):'轻触卡片，查看例句翻译'}</p>`:''}</div>`:''}</div>`}
function toggleCardReveal(){
 const w=activeWords()[card];if(!w)return;
 flipped=!flipped;const settings=state.cardSettings;
 const meaning=$('[data-card-meaning]');
 if(meaning)meaning.textContent=flipped||settings.meaning==='on'?(w.meaning||'暂无释义'):'轻触卡片，查看释义';
 const translation=$('[data-card-example-translation]');
 if(translation)translation.textContent=flipped||settings.exampleTranslation==='on'?(w.exampleTranslation||'暂无例句翻译'):'轻触卡片，查看例句翻译';
}
function chapterFilterMarkup(){const n=library.notebooks.find(n=>n.id===notebook),b=library.books.find(b=>b.id===n?.bookId);if(!b)return '';return `<label>按课查看词汇<select id="word-chapter-filter"><option value="all">整本词汇</option>${b.chapters.map(c=>`<option value="${esc(c.id)}" ${chapterFilter===c.id?'selected':''}>${esc(c.title)}</option>`).join('')}</select></label>`}
document.addEventListener('change',e=>{if(e.target.id==='word-chapter-filter'){stopCards();chapterFilter=e.target.value;card=0;flipped=false;vocab()}});
function vocab(){let title='Unas Dias';if(notebook)title=library.notebooks.find(n=>n.id===notebook)?.title||'词本';if(singleWords)title='词条';const shelf=!notebook&&!singleWords&&tab==='notebooks';const list=shelf?[]:activeWords();card=Math.min(card,Math.max(0,list.length-1));const w=list[card];shell(`<div class="section-head"><h2>${notebook||singleWords?'<button data-action="shared-back" aria-label="返回">←</button>':''}${esc(title)}</h2><div class="row">${!shelf?`<button class="secondary" data-action="shared-view">${wordView==='list'?'卡片模式':'条目模式'}</button>${ib('settings','card-settings','通用词汇显示设置')}${ib(autoCards?'pause':'play','card-auto',autoCards?'停止连续播放':'连续播放词汇')}`:''}</div></div>${!notebook&&!singleWords?`<p class="note">Remember Me</p><div class="filters">${[['recent','最近接触'],['favorites','我的收藏'],['notebooks','我的词本'],['learning','我的学习']].map(([id,t])=>`<button class="chip ${tab===id?'active':''}" data-shared-tab="${id}">${t}</button>`).join('')}${shelf?ib(view==='grid'?'list':'grid','view','切换书架视图'):''}</div>`:''}${notebook?chapterFilterMarkup():''}${tab==='learning'&&!notebook&&!singleWords?`<div class="filters">${[['due','到期与新词'],['all','全部'],['stranger','陌生'],['vague','模糊'],['familiar','熟悉']].map(([id,t])=>`<button class="chip ${studyFilter===id?'active':''}" data-study-filter="${id}">${t}</button>`).join('')}</div><p class="note">简单间隔复习：陌生 10 分钟、模糊 1 天、首次熟悉 3 天，连续熟悉逐步延长。不是 FSRS，也不代表准确预测记忆。</p>`:''}${shelf?`<div class="${view}">${library.notebooks.map(n=>`<button class="book" data-notebook="${esc(n.id)}"><div class="cover"><span class="ar">كلمات</span><small>MY VOCABULARY</small></div><div class="book-info"><h3>${esc(n.title)}</h3><p>${n.words.length} 个单词</p></div></button>`).join('')}</div>`:!list.length?'<div class="empty">暂无符合条件的单词。可在词本中学习或切换筛选。</div>':wordView==='list'?list.map(wordRow).join(''):`${cardMarkup(w)}<div class="card-position">${card+1} / ${list.length} · 左右滑动或使用键盘方向键切换${autoCards?' · 连续播放中':''}</div><div class="rating-row"><button data-rating="stranger">陌生</button><button data-rating="vague">模糊</button><button data-rating="familiar">熟悉</button></div><p class="note">${w.audio?'音频由材料包提供':'本词暂无音频；连续模式将按设置停留后切换。'}</p>`}`);bindCardSwipe()}
function stopCards(){autoCards=false;autoGeneration++;clearTimeout(autoHandle);cardAudio.onended=null;cardAudio.onerror=null;cardAudio.pause();if(cardAudioUrl){URL.revokeObjectURL(cardAudioUrl);cardAudioUrl=null}}
function advanceCard(direction,automatic=false){if(!automatic)stopCards();const list=activeWords();if(!list.length)return;card=Math.max(0,Math.min(list.length-1,card+direction));flipped=false;if(automatic&&wordView==='list')updateWordPlaybackUi();else vocab()}
function updateWordPlaybackUi(){const position=$('.card-position');if(position)position.textContent=`${card+1} / ${activeWords().length} · 左右滑动切换${autoCards?' · 连续播放中':''}`;document.querySelectorAll('[data-action="card-auto"]').forEach(el=>{el.innerHTML=icon(autoCards?'pause':'play');el.setAttribute('aria-label',autoCards?'停止连续播放':'连续播放词汇')});document.querySelectorAll('[data-word-index]').forEach(el=>el.classList.toggle('word-playing',+el.dataset.wordIndex===card&&(autoCards||!cardAudio.paused)));}
async function pronounceAt(index){const list=activeWords();if(!Number.isInteger(index)||index<0||index>=list.length)return;const resume=autoCards;stopCards();audio.pause();card=index;autoCards=resume;updateWordPlaybackUi();await runCard(true)}
async function runCard(manual=false){const generation=++autoGeneration,w=activeWords()[card];if((!autoCards&&!manual)||!w)return;
 const next=()=>{if(!autoCards||generation!==autoGeneration)return;if(card>=activeWords().length-1){stopCards();updateWordPlaybackUi();return}advanceCard(1,true);runCard()};
 const delay=()=>{if(generation!==autoGeneration)return;updateWordPlaybackUi();if(autoCards)autoHandle=setTimeout(next,Math.max(1,state.cardSettings.seconds)*1000)};
 if(!w.audio){if(manual)toast('本词暂无配套音频');delay();return}
 const blob=await read('assets',(w._assetOwner||'')+'/'+w.audio);if(generation!==autoGeneration||(!autoCards&&!manual))return;
 if(!blob){toast('词音频缺失');delay();return}if(cardAudioUrl)URL.revokeObjectURL(cardAudioUrl);cardAudioUrl=URL.createObjectURL(blob);cardAudio.src=cardAudioUrl;
 cardAudio.onended=delay;cardAudio.onerror=()=>{if(generation!==autoGeneration)return;toast('词音频无法播放');delay()};
 try{await cardAudio.play();if(generation===autoGeneration)updateWordPlaybackUi()}catch{if(generation!==autoGeneration)return;stopCards();updateWordPlaybackUi();toast('无法播放词音频，请再次点击单词')}
}
function bindCardSwipe(){const el=$('.flash');if(!el)return;let start=null,suppress=false;el.onpointerdown=e=>{start={x:e.clientX,y:e.clientY}};el.onpointerup=e=>{if(!start)return;const dx=e.clientX-start.x,dy=e.clientY-start.y;start=null;if(Math.abs(dx)>55&&Math.abs(dx)>Math.abs(dy)){suppress=true;lastCardSwipe=Date.now();advanceCard(dx<0?1:-1)}};el.onpointercancel=()=>start=null;el.onclick=e=>{if(suppress){e.stopImmediatePropagation();suppress=false}};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){if(e.target!==el)return;e.preventDefault();toggleCardReveal()}}}
function cardSettings(){stopCards();const s=state.cardSettings;modal('通用词汇显示设置',`<p class="note">条目与卡片共用；例句原文和例句翻译分别控制。</p><label>单词释义<select id="cs-meaning"><option value="tap">点击显示</option><option value="on">默认显示</option></select></label><label><input id="cs-example" type="checkbox" ${s.example?'checked':''}> 显示例句原文（条目与卡片）</label><label>例句翻译<select id="cs-exampleTranslation"><option value="tap">点击显示</option><option value="on">默认显示</option><option value="off">不显示</option></select></label><label><input id="cs-transliteration" type="checkbox" ${s.transliteration?'checked':''}> 显示拉丁字母转写（如 marhaba）</label><label>音频结束或无音频时停留秒数<input id="cs-seconds" type="number" min="1" max="120" value="${s.seconds}"></label>`);for(const k of ['meaning','exampleTranslation'])$('#cs-'+k).value=s[k];for(const k of ['meaning','example','exampleTranslation','transliteration','seconds'])$('#cs-'+k).onchange=e=>{const v=e.target.type==='checkbox'?e.target.checked:e.target.value;if(k==='seconds'&&(!Number.isFinite(+v)||+v<1||+v>120)){toast('请输入 1–120 秒');e.target.value=s.seconds;return}s[k]=k==='seconds'?+v:v;persist();vocab()}}
function sleepSettings(){modal('定时停止播放',`<p id="sleep-status">${sleepDeadline?'将在约 '+Math.ceil((sleepDeadline-Date.now())/60000)+' 分钟后停止':'未开启'}</p><div class="row">${[15,30,45,60].map(n=>`<button class="secondary" data-sleep="${n}">${n} 分钟</button>`).join('')}</div><form id="sleep-form"><label>自定义分钟数<input id="sleep-minutes" type="number" min="1" max="1440" required></label><button class="primary">开始计时</button></form><button class="setting" data-sleep="0">取消定时</button><p class="note">从确认时起计时，到时暂停章节音频和卡片播放；手机后台可能延迟执行。</p>`);$('#sleep-form').onsubmit=e=>{e.preventDefault();setSleep(+$('#sleep-minutes').value)}}
function setSleep(minutes){if(!Number.isFinite(minutes)||minutes<0||minutes>1440)return toast('请输入 1–1440 分钟');sleepDeadline=minutes?Date.now()+minutes*60000:0;$('#panel').close();toast(minutes?`将在 ${minutes} 分钟后停止播放`:'已取消定时')}
function checkSleep(){if(sleepDeadline&&Date.now()>=sleepDeadline){sleepDeadline=0;audio.pause();stopCards();if(!reader&&page==='vocab')vocab();toast('定时结束，已停止播放')}}
setInterval(checkSleep,1000);document.addEventListener('visibilitychange',checkSleep);audio.addEventListener('timeupdate',checkSleep);cardAudio.addEventListener('timeupdate',checkSleep);
document.addEventListener('keydown',e=>{if(page==='vocab'&&wordView==='card'&&!$('#panel').open&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName)){if(e.key==='ArrowLeft')advanceCard(-1);if(e.key==='ArrowRight')advanceCard(1)}});
document.addEventListener('click',e=>{const el=e.target.closest('button,[data-action]');if(!el)return;const a=el.dataset.action;const handled=['shared-view','shared-flip','shared-back','card-settings','card-auto','sleep-settings','lookup-card'];if(el.dataset.entryTranslation!==undefined){e.preventDefault();e.stopImmediatePropagation();const w=activeWords()[+el.dataset.entryTranslation];if(w){const open=el.getAttribute('aria-expanded')==='true';el.textContent=open?'点击显示例句翻译':w.exampleTranslation||'暂无例句翻译';el.setAttribute('aria-expanded',String(!open))}return}if(el.dataset.pronounceIndex!==undefined){e.preventDefault();e.stopImmediatePropagation();if(Date.now()-lastCardSwipe>=350)pronounceAt(+el.dataset.pronounceIndex);return}if(el.dataset.rating||el.dataset.sharedTab||el.dataset.studyFilter||el.dataset.sleep!==undefined||handled.includes(a)){e.preventDefault();e.stopImmediatePropagation();if(el.dataset.rating)return rateCurrent(el.dataset.rating);if(el.dataset.sharedTab){stopCards();tab=el.dataset.sharedTab;notebook=null;singleWords=null;card=0;flipped=false;return vocab()}if(el.dataset.studyFilter){stopCards();studyFilter=el.dataset.studyFilter;card=0;return vocab()}if(el.dataset.sleep!==undefined)return setSleep(+el.dataset.sleep);switch(a){case 'shared-view':stopCards();wordView=wordView==='list'?'card':'list';state.wordView=wordView;persist();card=0;flipped=false;return vocab();case 'shared-flip':if(Date.now()-lastCardSwipe<350)return;return toggleCardReveal();case 'shared-back':stopCards();notebook=null;singleWords=null;return vocab();case 'card-settings':return cardSettings();case 'card-auto':if(autoCards)stopCards();else{audio.pause();autoCards=true;runCard()}updateWordPlaybackUi();return;case 'sleep-settings':return sleepSettings();case 'lookup-card':{const w=selectedLookupWord;$('#panel').close();audio.pause();reader=null;page='vocab';singleWords=w?[w]:[];notebook=null;wordView='card';card=0;flipped=false;return vocab()}}}if(el.dataset.page||el.dataset.book||el.dataset.notebook||el.dataset.word||a==='word-view'){stopCards();if(el.dataset.notebook)chapterFilter='all';singleWords=null;card=0;flipped=false}},true);

state.personalization={pageBackground:'#faf9f5',iconColor:'#28735e',bannerText:'MIY FLIZ',launcherColor:'green',...state.personalization};
let profileBackgroundUrl=null;
const iconPalettes={green:'#28735e',blue:'#366eab',rose:'#ad5269',amber:'#b17a24',purple:'#7956a5'};
const nativeIconPlugin=globalThis.Capacitor?.isNativePlatform?.()?globalThis.Capacitor.registerPlugin('AppIcon'):null;
function applyPersonalization(){const p=state.personalization||{},valid=c=>/^#[0-9a-f]{6}$/i.test(c),background=valid(p.pageBackground)?p.pageBackground:'#faf9f5',icons=valid(p.iconColor)?p.iconColor:'#28735e';const rgb=background.slice(1).match(/../g).map(x=>parseInt(x,16)),dark=rgb.reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0)<115;const style=document.documentElement.style;style.setProperty('--paper',background);style.setProperty('--icon',icons);style.setProperty('--ink',dark?'#e6eee8':'#213e38');style.setProperty('--muted',dark?'#adbbb0':'#80958b');style.setProperty('--surface',dark?'#29382f':'#fffdf9');style.setProperty('--line',dark?'#4c5e52':'#dfe5dc');style.setProperty('--light',dark?'#354b3e':'#e9efe4');document.documentElement.dataset.theme=dark?'dark':'light';const title=$('#profile-banner-title');if(title)title.textContent=p.bannerText||'MIY FLIZ';document.querySelectorAll('.profile-hero').forEach(el=>{el.classList.toggle('custom-background',!!profileBackgroundUrl);el.style.backgroundImage=profileBackgroundUrl?`url("${profileBackgroundUrl}")`:''})}
async function loadProfileBackground(){if(profileBackgroundUrl)URL.revokeObjectURL(profileBackgroundUrl);profileBackgroundUrl=null;const blob=await read('content','personalization-background');if(blob)profileBackgroundUrl=URL.createObjectURL(blob);applyPersonalization()}
async function storeProfileBackground(blob){await new Promise((resolve,reject)=>{const tx=db.transaction('content','readwrite'),s=tx.objectStore('content');if(blob)s.put(blob,'personalization-background');else s.delete('personalization-background');tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)});await loadProfileBackground()}
async function exportBackground(){const blob=await read('content','personalization-background');if(!blob)return null;return new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.readAsDataURL(blob)})}
async function backgroundFromBackup(value){if(!value)return null;if(typeof value!=='string'||value.length>12*1024*1024||!/^data:image\/(png|jpeg|webp);base64,/.test(value))throw Error('备份背景图片格式无效');const blob=await fetch(value).then(r=>r.blob());await createImageBitmap(blob).then(image=>image.close());return blob}
function personalizationSettings(){modal('个性化设置',`<label>内页背景颜色<input id="personal-background" type="color" value="${esc(state.personalization.pageBackground)}"></label><label>页面图标颜色<input id="personal-icons" type="color" value="${esc(state.personalization.iconColor)}"></label><label>手机桌面图标<select id="personal-launcher">${Object.entries(iconPalettes).map(([k,color])=>`<option value="${k}" ${state.personalization.launcherColor===k?'selected':''}>${{green:'绿色',blue:'蓝色',rose:'玫瑰色',amber:'琥珀色',purple:'紫色'}[k]}</option>`).join('')}</select></label><div class="launcher-preview" style="background:${iconPalettes[state.personalization.launcherColor]||iconPalettes.green}">${icon('book')}</div><p class="note">${nativeIconPlugin?'桌面图标更新可能需要启动器刷新。':'桌面图标切换将在 Android 安装版生效；网页可保存选择。'}</p><label>展板文字<input id="personal-banner-text" maxlength="100" value="${esc(state.personalization.bannerText)}"></label><label>展板背景图片<input id="personal-banner-image" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="secondary" id="personal-clear-image">清除背景图片</button>`);
 $('#personal-background').oninput=e=>{state.personalization.pageBackground=e.target.value;persist();applyPersonalization()};$('#personal-icons').oninput=e=>{state.personalization.iconColor=e.target.value;persist();applyPersonalization()};$('#personal-banner-text').oninput=e=>{state.personalization.bannerText=e.target.value;persist();applyPersonalization()};
 $('#personal-launcher').onchange=async e=>{const value=e.target.value,old=state.personalization.launcherColor;e.target.disabled=true;try{if(nativeIconPlugin)await nativeIconPlugin.setColor({color:value});state.personalization.launcherColor=value;persist();$('.launcher-preview').style.background=iconPalettes[value];toast(nativeIconPlugin?'已请求更换桌面图标':'桌面图标配色已保存')}catch(error){e.target.value=old;toast('图标切换失败：'+error.message)}finally{e.target.disabled=false}};
 $('#personal-banner-image').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>8*1024*1024)throw Error('请选择不超过 8MB 的 PNG、JPEG 或 WebP');await createImageBitmap(file).then(image=>image.close());await storeProfileBackground(file);toast('展板背景已更新')}catch(error){toast(error.message)}finally{e.target.value=''}};$('#personal-clear-image').onclick=async()=>{await storeProfileBackground(null);toast('已清除背景图片')};
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="personalization"]'))personalizationSettings()});
await loadProfileBackground();

render();
